/**
 * Browser helper for WebSocket routes generated by Litestar's ChannelsPlugin.
 *
 * @example
 * ```ts
 * import { createChannelsStream } from "litestar-vite-plugin/helpers"
 *
 * const stream = createChannelsStream({
 *   basePath: "/ws",
 *   channel: "notifications",
 *   onEvent: (event) => console.log(event),
 * })
 * stream.connect()
 * ```
 *
 * @module
 */

import { createEventStream, type EventStream, type EventStreamConfig, resolveStreamUrl } from "./stream.js"

export type ChannelName = string | (() => string)

export interface ChannelsStreamOptions<
  TFrame = unknown,
  TParams extends Record<string, string | number> = Record<string, string | number>,
> extends Omit<EventStreamConfig<TFrame>, "EventSourceCtor" | "sseEvents" | "transport"> {
  channel: ChannelName
  params?: TParams
  basePath?: string
  transformUrl?: (url: URL) => string | URL
}

/**
 * Create a stream for a WebSocket route generated by ChannelsPlugin.
 *
 * @param options - Channel name, optional path parameters, server route prefix, and stream callbacks.
 * @returns A disposable stream that connects only when `connect()` is called.
 */
export function createChannelsStream<
  TFrame = unknown,
  TParams extends Record<string, string | number> = Record<string, string | number>,
>(options: ChannelsStreamOptions<TFrame, TParams>): EventStream {
  const { basePath = "/", channel, params, transformUrl, ...streamOptions } = options
  return createEventStream({
    ...streamOptions,
    buildUrl: () => {
      let channelName = typeof channel === "function" ? channel() : channel
      let resolvedPath: string
      if (params && typeof params === "object") {
        channelName = channelName.replace(/\{([^{}]+)\}/g, (_, key) => {
          const val = params[key]
          return val !== undefined ? encodeURIComponent(String(val)) : `{${key}}`
        })
        const cleanChannel = channelName.startsWith("/") ? channelName.slice(1) : channelName
        resolvedPath = cleanChannel
          .split("/")
          .map((seg) => {
            try {
              return encodeURIComponent(decodeURIComponent(seg))
            } catch {
              return encodeURIComponent(seg)
            }
          })
          .join("/")
      } else {
        resolvedPath = encodeURIComponent(channelName)
      }
      const prefix = basePath.endsWith("/") ? basePath : `${basePath}/`
      const url = new URL(resolveStreamUrl(`${prefix}${resolvedPath}`, "websocket"))
      return transformUrl?.(url) ?? url
    },
    transport: "websocket",
  })
}
